/**
 * Independent acceptance expectations for local release preparation, before consumer implementation.
 * Run `node --test scripts/acceptance-preparation.test.mjs` with pinned Node once the implementation is available.
 * Compact temporary Git histories reuse the genesis/candidate shapes from the admission fixtures; expected decisions
 * are literal test data, never generated by the production resolver. Tests read/write only disposable local fixtures.
 * No Docker, product execution, credentials, network, remote Git, publication or cloud operation is performed.
 * The verifier must return the required suite or throw before release export; local replay never creates CI authority.
 */
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import test from "node:test";
import { verifyPreparationAcceptance } from "./acceptance-preparation.mjs";

const repository = "example/private-mp3";
const registryPath = "docs/testing/acceptance-transitions.json";
const fixturePath = "tests/acceptance/fixtures/manifest.json";
const sha256 = (bytes) => createHash("sha256").update(bytes).digest("hex");

/** Independent canonical JSON oracle for synthetic trusted CI output, preserving array order. */
function canonical(value) {
  if (Array.isArray(value)) return `[${value.map(canonical).join(",")}]`;
  if (value && typeof value === "object") {
    return `{${Object.keys(value)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${canonical(value[key])}`)
      .join(",")}}`;
  }
  return JSON.stringify(value);
}

function fixture(t, { policy = true } = {}) {
  const root = mkdtempSync(join(tmpdir(), "mp3-acceptance-preparation-"));
  t.after(() => rmSync(root, { recursive: true, force: true }));
  const git = (...args) =>
    execFileSync(
      "git",
      ["-c", "user.name=Independent Preparation Fixture", "-c", "user.email=preparation@example.invalid", ...args],
      { cwd: root, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] },
    ).trim();
  const put = (path, bytes) => {
    mkdirSync(dirname(join(root, path)), { recursive: true });
    writeFileSync(join(root, path), bytes);
  };
  const json = (path, value) => put(path, `${JSON.stringify(value, null, 2)}\n`);
  const commit = (message) => {
    git("add", "--all");
    git("commit", "--quiet", "-m", message);
    return git("rev-parse", "HEAD");
  };
  git("init", "--quiet", "--initial-branch=main");
  put("README.md", "Synthetic preparation fixture.\n");
  commit("foundation");
  json("tests/acceptance/package.json", { private: true, scripts: { check: "node check.mjs" } });
  put("tests/acceptance/check.mjs", "// Independent synthetic suite; never executed.\n");
  json(fixturePath, { contractRevision: "r3", independentCount: 3 });
  put("docs/testing/acceptance-contract.md", "# Immutable synthetic r3 contract\n");
  const genesisCommit = commit("independent pre-product suite");
  const genesis = {
    schemaVersion: 1,
    contractRevision: "r3",
    suiteCommit: genesisCommit,
    suiteTree: git("rev-parse", `${genesisCommit}:tests/acceptance`),
    manifestSha256: sha256(readFileSync(join(root, fixturePath))),
    publicationStatus: "protected-main",
  };
  json("docs/testing/baseline.json", genesis);
  put("server/src/parser.ts", "// Synthetic product; never executed.\n");
  put("server/Dockerfile", "# Synthetic runtime; never built.\n");
  put("compose.yaml", "services: {}\n");
  const product = commit("product after independent genesis");
  const registry = { schemaVersion: 1, transitions: [] };
  if (policy) json(registryPath, registry);
  const source = policy ? commit("dormant transition policy") : product;
  const resolution = {
    genesis,
    required: genesis,
    candidate: null,
    pendingBinding: null,
    admission: policy ? "bootstrap" : "legacy",
    bindingCommit: null,
    activationCommit: null,
    policySha256: policy ? sha256(readFileSync(join(root, registryPath))) : null,
  };
  const candidate = () => {
    git("checkout", "--quiet", "-b", "independent-candidate");
    json(fixturePath, { contractRevision: "r4", independentCount: 3 });
    put("tests/acceptance/check.mjs", "// Independent transport successor; never executed.\n");
    const contractPath = "docs/testing/contracts/transport-r4.md";
    put(contractPath, "# Synthetic transport r4\n");
    const reviewedHead = commit("independently reviewed candidate feature");
    const reviewedTree = git("rev-parse", `${reviewedHead}^{tree}`);
    git("checkout", "--quiet", "main");
    git("merge", "--squash", "--quiet", "independent-candidate");
    const suiteCommit = commit("actual candidate squash");
    assert.notEqual(reviewedHead, suiteCommit);
    const entry = {
      id: "transport-r4",
      predecessor: "r3",
      contractRevision: "r4",
      contractPath,
      contractSha256: sha256(readFileSync(join(root, contractPath))),
      suiteCommit,
      suiteTree: git("rev-parse", `${suiteCommit}:tests/acceptance`),
      manifestSha256: sha256(readFileSync(join(root, fixturePath))),
      review: {
        repository,
        pullRequest: 12,
        reviewId: 34,
        reviewer: "independent-reviewer",
        reviewedHead,
        reviewedTree,
      },
    };
    const { review: _review, ...candidateFields } = entry;
    const candidateResolution = {
      ...resolution,
      admission: "candidate",
      candidate: { schemaVersion: 1, ...candidateFields, publicationStatus: "candidate" },
    };
    const bind = () => {
      registry.transitions.push(entry);
      json(registryPath, registry);
      const binding = commit("bind reviewed candidate squash");
      const pendingBinding = { schemaVersion: 1, ...entry, publicationStatus: "protected-main" };
      const bindingResolution = {
        ...resolution,
        pendingBinding,
        admission: "binding",
        bindingCommit: binding,
        policySha256: sha256(readFileSync(join(root, registryPath))),
      };
      const observation = {
        ...entry.review,
        author: "product-owner",
        baseRef: "main",
        merged: true,
        mergeCommit: suiteCommit,
        state: "APPROVED",
      };
      return { binding, resolution: bindingResolution, observation };
    };
    return { entry, resolution: candidateResolution, bind };
  };
  return { root, git, put, json, commit, genesis, product, source, resolution, candidate };
}

/** Full successful local report shape keeps acceptance-consumer failures separate from unrelated report validation. */
function report(sourceRevision, baseline) {
  return {
    schemaVersion: 1,
    status: "passed",
    cleanup: "passed",
    targetKind: "local",
    sourceDirty: false,
    trackedDiffSha256: sha256(""),
    sourceRevision,
    suiteCommit: baseline.suiteCommit,
    suiteTree: baseline.suiteTree,
    manifestSha256: baseline.manifestSha256,
    contractRevision: baseline.contractRevision,
    baselinePublication: baseline.publicationStatus,
    configurationSha256: "5".repeat(64),
    project: "mp3-e2e-acceptance-preparation",
    acceptance: { status: "passed", planned: 60, passed: 60, failed: 0, skipped: 0 },
    images: { api: `sha256:${"a".repeat(64)}`, frontend: `sha256:${"b".repeat(64)}` },
  };
}

function localReport(f, sourceRevision = f.source, baseRevision = f.product, resolution = f.resolution) {
  return {
    ...report(sourceRevision, resolution.required),
    localSelection: { kind: "local-acceptance-resolution", sourceRevision, baseRevision, resolution },
  };
}

function ciReport(
  f,
  sourceRevision = f.source,
  baseRevision = f.product,
  resolution = f.resolution,
  observedReviews = [],
) {
  const record = {
    schemaVersion: 1,
    kind: "ci-acceptance-admission",
    context: {
      repository,
      eventName: "push",
      ref: "refs/heads/main",
      sourceRevision,
      sourceTree: f.git("rev-parse", `${sourceRevision}^{tree}`),
      baseRevision,
      workflowRevision: sourceRevision,
      toolingRevision: baseRevision,
      runId: 42001,
      attempt: 1,
    },
    observedReviews,
    resolution,
  };
  const digest = sha256(canonical(record));
  return {
    report: { ...report(sourceRevision, resolution.required), acceptanceAdmission: { record, sha256: digest } },
    env: {
      CI: "true",
      CI_BASE_REF: baseRevision,
      GITHUB_ACTIONS: "true",
      GITHUB_SERVER_URL: "https://github.com",
      GITHUB_API_URL: "https://api.github.com",
      GITHUB_REPOSITORY: repository,
      GITHUB_SHA: sourceRevision,
      GITHUB_WORKFLOW_SHA: sourceRevision,
      GITHUB_WORKFLOW_REF: `${repository}/.github/workflows/ci.yml@refs/heads/main`,
      GITHUB_EVENT_NAME: "push",
      GITHUB_REF: "refs/heads/main",
      GITHUB_RUN_ID: "42001",
      GITHUB_RUN_ATTEMPT: "1",
      GATE_ADMISSION_SHA256: digest,
    },
  };
}

test("legacy preparation preserves genesis identity checks and refuses either new evidence claim", (t) => {
  const f = fixture(t, { policy: false });
  const original = report(f.source, f.genesis);
  assert.deepEqual(verifyPreparationAcceptance(f.root, original, {}), f.genesis);
  for (const field of ["localSelection", "acceptanceAdmission"]) {
    for (const value of [null, {}])
      assert.throws(() => verifyPreparationAcceptance(f.root, { ...original, [field]: value }, {}));
  }
  for (const fields of [
    { suiteCommit: f.product },
    { suiteTree: "0".repeat(40) },
    { manifestSha256: "0".repeat(64) },
    { contractRevision: "r4" },
    { baselinePublication: "provisional" },
  ])
    assert.throws(() => verifyPreparationAcceptance(f.root, { ...original, ...fields }, {}));
  f.put("tests/acceptance/check.mjs", "// Illegal legacy suite edit.\n");
  const changed = f.commit("legacy source changed frozen suite");
  assert.throws(() => verifyPreparationAcceptance(f.root, { ...original, sourceRevision: changed }, {}));

  const later = fixture(t, { policy: false });
  const falseGenesis = { ...later.genesis, suiteCommit: later.product };
  later.json("docs/testing/baseline.json", falseGenesis);
  const falseSource = later.commit("invalid post-product genesis claim");
  assert.throws(() => verifyPreparationAcceptance(later.root, report(falseSource, falseGenesis), {}));
});

test("local preparation replays the original source and base from a newer tooling and candidate checkout", (t) => {
  const f = fixture(t);
  const original = localReport(f);
  const originalBytes = JSON.stringify(original);
  assert.deepEqual(verifyPreparationAcceptance(f.root, original, {}), f.genesis);
  f.put("README.md", "Newer preparation documentation.\n");
  f.commit("later preparation tooling state");
  assert.deepEqual(verifyPreparationAcceptance(f.root, original, {}), f.genesis);
  f.candidate();
  assert.notEqual(f.git("rev-parse", "HEAD:tests/acceptance"), f.genesis.suiteTree);
  assert.deepEqual(verifyPreparationAcceptance(f.root, original, {}), f.genesis);
  assert.equal(JSON.stringify(original), originalBytes);
  assert.deepEqual(verifyPreparationAcceptance(f.root, report(f.product, f.genesis), {}), f.genesis);
});

test("post-policy CI preparation requires independent digest and the exact current original-attempt context", (t) => {
  const f = fixture(t);
  const value = ciReport(f);
  assert.deepEqual(verifyPreparationAcceptance(f.root, value.report, value.env), f.genesis);
  for (const field of [
    "GATE_ADMISSION_SHA256",
    "CI_BASE_REF",
    "GITHUB_ACTIONS",
    "GITHUB_SERVER_URL",
    "GITHUB_API_URL",
    "GITHUB_REPOSITORY",
    "GITHUB_SHA",
    "GITHUB_WORKFLOW_SHA",
    "GITHUB_WORKFLOW_REF",
    "GITHUB_EVENT_NAME",
    "GITHUB_REF",
    "GITHUB_RUN_ID",
    "GITHUB_RUN_ATTEMPT",
  ]) {
    const env = { ...value.env };
    delete env[field];
    assert.throws(() => verifyPreparationAcceptance(f.root, value.report, env), field);
  }
  for (const fields of [
    { GATE_ADMISSION_SHA256: "0".repeat(64) },
    { CI_BASE_REF: f.genesis.suiteCommit },
    { GITHUB_SHA: f.product, GITHUB_WORKFLOW_SHA: f.product },
    { GITHUB_REPOSITORY: "other/private-mp3" },
    { GITHUB_SERVER_URL: "https://github.example.invalid" },
    { GITHUB_API_URL: "https://api.example.invalid" },
    { GITHUB_WORKFLOW_REF: `${repository}/.github/workflows/other.yml@refs/heads/main` },
    { GITHUB_RUN_ID: "42002" },
    { GITHUB_RUN_ATTEMPT: "2" },
  ])
    assert.throws(() => verifyPreparationAcceptance(f.root, value.report, { ...value.env, ...fields }));
  for (const acceptanceAdmission of [undefined, null, {}, { record: value.report.acceptanceAdmission.record }]) {
    assert.throws(() => verifyPreparationAcceptance(f.root, { ...value.report, acceptanceAdmission }, value.env));
  }
  const changed = structuredClone(value.report);
  changed.acceptanceAdmission.record.resolution.admission = "documentation";
  assert.throws(() => verifyPreparationAcceptance(f.root, changed, value.env));
  changed.acceptanceAdmission.sha256 = sha256(canonical(changed.acceptanceAdmission.record));
  assert.throws(() =>
    verifyPreparationAcceptance(f.root, changed, {
      ...value.env,
      GATE_ADMISSION_SHA256: changed.acceptanceAdmission.sha256,
    }),
  );
});

test("local preparation requires closed exact selection and rejects admission, digest or CI impersonation", (t) => {
  const f = fixture(t);
  const original = localReport(f);
  for (const localSelection of [
    undefined,
    null,
    {},
    { ...original.localSelection, extra: true },
    { ...original.localSelection, kind: "ci-acceptance-admission" },
    { ...original.localSelection, sourceRevision: f.product },
    { ...original.localSelection, baseRevision: f.genesis.suiteCommit },
    { ...original.localSelection, resolution: { ...f.resolution, admission: "documentation" } },
  ])
    assert.throws(() => verifyPreparationAcceptance(f.root, { ...original, localSelection }, {}));
  for (const env of [
    { GATE_ADMISSION_SHA256: "1".repeat(64) },
    { GATE_ADMISSION_PATH: "/synthetic/unused-record.json" },
    { GITHUB_ACTIONS: "true" },
  ])
    assert.throws(() => verifyPreparationAcceptance(f.root, original, env));
  for (const acceptanceAdmission of [null, {}, ciReport(f).report.acceptanceAdmission]) {
    assert.throws(() => verifyPreparationAcceptance(f.root, { ...original, acceptanceAdmission }, {}));
  }
  const ci = ciReport(f);
  assert.throws(() =>
    verifyPreparationAcceptance(f.root, { ...ci.report, localSelection: original.localSelection }, ci.env),
  );
});

test("candidate and independently reviewed binding prepare only the prior required suite", (t) => {
  const f = fixture(t);
  const candidate = f.candidate();
  const candidateReport = localReport(f, candidate.entry.suiteCommit, f.source, candidate.resolution);
  assert.deepEqual(verifyPreparationAcceptance(f.root, candidateReport, {}), f.genesis);
  const wrongCandidate = {
    ...candidateReport,
    ...report(candidate.entry.suiteCommit, {
      ...candidate.entry,
      publicationStatus: "protected-main",
    }),
  };
  assert.throws(() => verifyPreparationAcceptance(f.root, wrongCandidate, {}));
  const bound = candidate.bind();
  const value = ciReport(f, bound.binding, candidate.entry.suiteCommit, bound.resolution, [bound.observation]);
  assert.deepEqual(verifyPreparationAcceptance(f.root, value.report, value.env), f.genesis);
  const unobserved = localReport(f, bound.binding, candidate.entry.suiteCommit, bound.resolution);
  assert.throws(() => verifyPreparationAcceptance(f.root, unobserved, {}));
  const wrongBinding = { ...value.report, ...report(bound.binding, bound.resolution.pendingBinding) };
  assert.throws(() => verifyPreparationAcceptance(f.root, wrongBinding, value.env));
});

test("activated successor remains required for preparation and descendants despite a genesis report claim", (t) => {
  const f = fixture(t);
  const candidate = f.candidate();
  const bound = candidate.bind();
  f.put("server/src/parser.ts", "// Product capability using reviewed successor; never executed.\n");
  const implementation = f.commit("activate the bound successor");
  const resolution = {
    ...bound.resolution,
    required: bound.resolution.pendingBinding,
    pendingBinding: null,
    admission: "implementation",
    activationCommit: implementation,
  };
  const active = localReport(f, implementation, bound.binding, resolution);
  assert.deepEqual(verifyPreparationAcceptance(f.root, active, {}), resolution.required);
  assert.throws(() => verifyPreparationAcceptance(f.root, { ...active, ...report(implementation, f.genesis) }, {}));
  f.put("README.md", "Documentation after successor activation.\n");
  const descendant = f.commit("successor remains required");
  const after = localReport(f, descendant, implementation, { ...resolution, admission: "documentation" });
  assert.deepEqual(verifyPreparationAcceptance(f.root, after, {}), resolution.required);
  assert.throws(() => verifyPreparationAcceptance(f.root, { ...after, ...report(descendant, f.genesis) }, {}));
});

test("missing history or policy deletion cannot select the legacy preparation path", (t) => {
  const f = fixture(t);
  const original = localReport(f);
  f.put(".git/shallow", `${f.product}\n`);
  assert.throws(() => verifyPreparationAcceptance(f.root, original, {}));
  rmSync(join(f.root, ".git/shallow"));
  rmSync(join(f.root, registryPath));
  const deleted = f.commit("invalid transition policy deletion");
  assert.throws(() => verifyPreparationAcceptance(f.root, report(deleted, f.genesis), {}));
  const legacyClaim = { ...f.resolution, admission: "legacy", policySha256: null };
  assert.throws(() => verifyPreparationAcceptance(f.root, localReport(f, deleted, f.source, legacyClaim), {}));
});
